module ham_distribution (\n    input [7:0] A0, \n    input [7:0] A1, \n    input [7:0] A2, \n    input [7:0] B0, \n    input [7:0] B1, \n    input [7:0] B2, \n    output reg signed [31:0] result\n);\n\n    // Q28.4 fixed-point format (28 integer, 4 fractional bits)\n    wire signed [31:0] A0_fp = A0 << 4;\n    wire signed [31:0] A1_fp = A1 << 4;\n    wire signed [31:0] A2_fp = A2 << 4;\n    wire signed [31:0] B0_fp = B0 << 4;\n    wire signed [31:0] B1_fp = B1 << 4;\n    wire signed [31:0] B2_fp = B2 << 4;\n\n    wire signed [31:0] S = B0_fp + B1_fp + B2_fp;\n\n    reg signed [31:0] lower_bound;\n    reg signed [31:0] upper_bound;\n\n    localparam signed [31:0] MAX_LAMBDA = 32\'sd10_000_000 << 4; // 0x0989_6800\n    localparam signed [31:0] NEG_MAX = -MAX_LAMBDA;\n\n    wire signed [31:0] deltaA01 = A0_fp - A1_fp;\n    wire signed [31:0] deltaB01 = B0_fp - B1_fp;\n    wire signed [63:0] numerator01 = -S * deltaA01;\n    wire signed [31:0] bound01 = (deltaB01 != 0) ? (numerator01 / deltaB01) : 0;\n\n    wire signed [31:0] deltaA12 = A1_fp - A2_fp;\n    wire signed [31:0] deltaB12 = B1_fp - B2_fp;\n    wire signed [63:0] numerator12 = -S * deltaA12;\n    wire signed [31:0] bound12 = (deltaB12 != 0) ? (numerator12 / deltaB12) : 0;\n\n    always @(*) begin\n        // Initialize bounds\n        lower_bound = 32\'s0;\n        upper_bound = MAX_LAMBDA;\n\n        // Process pair (0,1)\n        if (deltaB01 == 0) begin\n            if (deltaA01 < 0) begin\n                lower_bound = MAX_LAMBDA;\n                upper_bound = NEG_MAX;\n            end\n        end else begin\n            if (deltaB01 > 0) begin\n                if (bound01 > lower_bound) lower_bound = bound01;\n            end else begin\n                if (bound01 < upper_bound) upper_bound = bound01;\n            end\n        end\n\n        // Process pair (1,2)\n        if (deltaB12 == 0) begin\n            if (deltaA12 < 0) begin\n                lower_bound = MAX_LAMBDA;\n                upper_bound = NEG_MAX;\n            end\n        end else begin\n            if (deltaB12 > 0) begin\n                if (bound12 > lower_bound) lower_bound = bound12;\n            end else begin\n                if (bound12 < upper_bound) upper_bound = bound12;\n            end\n        end\n\n        // Clamp lower bound\n        if (lower_bound < 0) lower_bound = 32\'s0;\n\n        // Final validity check\n        if (lower_bound > upper_bound || lower_bound > MAX_LAMBDA || upper_bound < 0) begin\n            result = -32\'s1; // Invalid value (all 1\'s)\n        end else begin\n            result = lower_bound;\n        end\n    end\n\nendmodule